<?php
namespace App\Http\Controllers\Storefront;
use App\Http\Controllers\Controller; use App\Http\Controllers\Storefront\Concerns\BuildsStorefrontQueries; use App\Models\Car; use App\Models\PartCategory; use Illuminate\Contracts\View\View; use Illuminate\Http\Request;
class CategoryController extends Controller { use BuildsStorefrontQueries; public function show(Request $request,string $path): View { $lastSegment=collect(explode('/',trim($path,'/')))->filter()->last(); $category=PartCategory::query()->where('category_path',trim($path,'/'))->orWhere('slug',$lastSegment)->firstOrFail(); return view('storefront.categories.show',['category'=>$category,'parts'=>$this->storefrontQuery($request)->forCategory($category)->paginate(60)->withQueryString(),'categories'=>PartCategory::query()->orderBy('name')->limit(80)->get(),'cars'=>Car::query()->select('make','model')->whereNotNull('make')->distinct()->orderBy('make')->limit(80)->get(),'metaTitle'=>$category->name.' - GPSwiss','metaDescription'=>'Szeroki wybór oryginalnych, używanych części samochodowych w kategorii '.$category->name.'.','breadcrumbs'=>[['label'=>'Strona główna','url'=>route('storefront.home')],['label'=>'Sklep','url'=>route('storefront.catalog')],['label'=>$category->name]]]); } }
